#[cfg(test)]
mod routing_tests {
    use super::*;
    #[test]
    fn four_high_bleed_mics_can_share_two_cameras_and_use_a_third() {
        let microphone_ids:Vec<String>=(1..=4).map(|i|format!("mic{i}")).collect();
        let cameras=vec![
            PodcastCameraMicrophones{channel_id:"wide1".into(),microphone_ids:microphone_ids[..3].to_vec()},
            PodcastCameraMicrophones{channel_id:"wide2".into(),microphone_ids:microphone_ids[..3].to_vec()},
            PodcastCameraMicrophones{channel_id:"single".into(),microphone_ids:vec!["mic4".into()]},
        ];
        let mut envelopes=vec![vec![0.65;1600];4];
        for mic in 0..4 {for v in &mut envelopes[mic][mic*400..(mic+1)*400] {*v=0.8;}}
        // Different recorder gain must not become a permanent speaker bias.
        for v in &mut envelopes[1] {*v*=4.0;}
        let cuts=crate::analyze_podcast_multicam(crate::AnalyzePodcastOptions{
            envelopes,channel_ids:vec!["wide1".into(),"wide2".into(),"single".into()],duration:16.,
            settings:crate::podcast_multicam_defaults(crate::PodcastMulticamDefaultsOptions{quick:true}),
            camera_windows:vec![],advanced:Some(AdvancedPodcastRouting{microphone_ids,cameras}),
        });
        assert_eq!(cuts.len(),2,"Shared microphones should not force extra camera switches");
        assert_eq!(cuts[0].channel_id,"wide1");assert_eq!(cuts[1].channel_id,"single");
        assert!((cuts.iter().map(|c|c.duration).sum::<f64>()-16.).abs()<1e-6);
    }
}
